package cep

import (
	"context"
	"reflect"

	"github.com/cloudwego/kitex/pkg/streaming"
)

// StreamEndpoint represents a client-side stream operation that returns a ClientStream.
type StreamEndpoint func(ctx context.Context) (st streaming.ClientStream, err error)

// StreamMiddleware is a chainable interceptor for StreamEndpoint.
type StreamMiddleware func(next StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder builds a middleware with information from a context.
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// StreamChain connects middlewares into one middleware.
// Middlewares are composed right-to-left.
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyDummyMiddleware returns the next endpoint unchanged.
// Note: the double "Dummy" in the name is intentional per the specification.
func DummyDummyMiddleware(next StreamEndpoint) StreamEndpoint {
	return next
}

// StreamRecvEndpoint represents a client-side stream recv operation.
type StreamRecvEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo returns true if this endpoint references the same underlying function as e2.
func (ep StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	if ep == nil && e2 == nil {
		return true
	}
	if ep == nil || e2 == nil {
		return false
	}
	return reflect.ValueOf(ep).Pointer() == reflect.ValueOf(e2).Pointer()
}

// StreamRecvMiddleware is a chainable interceptor for StreamRecvEndpoint.
type StreamRecvMiddleware func(next StreamRecvEndpoint) StreamRecvEndpoint

// StreamRecvMiddlewareBuilder builds a middleware with information from a context.
type StreamRecvMiddlewareBuilder func(ctx context.Context) StreamRecvMiddleware

// StreamRecvChain connects middlewares into one middleware.
// Middlewares are composed right-to-left.
func StreamRecvChain(mws ...StreamRecvMiddleware) StreamRecvMiddleware {
	return func(next StreamRecvEndpoint) StreamRecvEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamSendEndpoint represents a client-side stream send operation.
type StreamSendEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo returns true if this endpoint references the same underlying function as e2.
func (ep StreamSendEndpoint) EqualsTo(e2 StreamSendEndpoint) bool {
	if ep == nil && e2 == nil {
		return true
	}
	if ep == nil || e2 == nil {
		return false
	}
	return reflect.ValueOf(ep).Pointer() == reflect.ValueOf(e2).Pointer()
}

// StreamSendMiddleware is a chainable interceptor for StreamSendEndpoint.
type StreamSendMiddleware func(next StreamSendEndpoint) StreamSendEndpoint

// StreamSendMiddlewareBuilder builds a middleware with information from a context.
type StreamSendMiddlewareBuilder func(ctx context.Context) StreamSendMiddleware

// StreamSendChain connects middlewares into one middleware.
// Middlewares are composed right-to-left.
func StreamSendChain(mws ...StreamSendMiddleware) StreamSendMiddleware {
	return func(next StreamSendEndpoint) StreamSendEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}
