// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0
	TTHeader    Protocol = 2
	Framed      Protocol = 4
	HTTP        Protocol = 8
	GRPC        Protocol = 16
	HESSIAN2    Protocol = 32

	TTHeaderStreaming Protocol = 64
	GRPCStreaming     Protocol = 128

	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle zero case
	if tp == 0 {
		return "PurePayload"
	}

	// Define all single-bit flags in ascending bit order
	flags := []struct {
		bit  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	var parts []string
	remaining := tp

	// Check each flag in ascending bit order
	for _, flag := range flags {
		if tp&flag.bit != 0 {
			parts = append(parts, flag.name)
			remaining &^= flag.bit
		}
	}

	// If we matched all bits, return the composite
	if remaining == 0 && len(parts) > 0 {
		if len(parts) == 1 {
